#pragma once

#include "src/Framework/event.hh"

// Input generated by the input manager.
class InputEvent : public Event
{
public:
    enum Direction
    {
        UP,
        DOWN,
        STOP
    };

    Direction direction;

    explicit InputEvent(Direction dir) : direction(dir) {}
};

// Collision types detected by the collision manager.
class CollisionEvent : public Event
{
public:
    enum Type
    {
        PLAYER_PADDLE,
        CPU_PADDLE,
        TOP_WALL, 
        BOTTOM_WALL,
        LEFT_WALL,
        RIGHT_WALL

    };

    Type type;

    explicit CollisionEvent(Type collisionType) : type(collisionType) {}
};
